document.addEventListener("DOMContentLoaded",()=>{

/* ---------------- MOBILE MENU ---------------- */
const mb=document.getElementById("mobileMenuBtn"),
mm=document.getElementById("mobileMenu"),
io=document.getElementById("iconOpen"),
ic=document.getElementById("iconClose");
if(mb){
 let o=0;
 mb.onclick=()=>{o=!o;
 mm.classList.toggle("max-h-0",!o);
 mm.classList.toggle("opacity-0",!o);
 mm.classList.toggle("max-h-[400px]",o);
 mm.classList.toggle("opacity-100",o);
 io.classList.toggle("hidden",o);
 ic.classList.toggle("hidden",!o);
};
}

/* ---------------- AUTO-SLIDER ---------------- */
let cs=0;
const slider=document.getElementById("servicesSlider");
if(slider){setInterval(()=>{cs=(cs+1)%3;slider.style.transform=`translateX(-${cs*20}%)`},3000);}

/* ---------------- TEXT STATE TOGGLER ---------------- */
const s1=document.getElementById("state1"),s2=document.getElementById("state2"),sw=document.getElementById("servicesWrapper");
if(s1&&s2&&sw){
 let st=1;
 setInterval(()=>{
  sw.style.opacity=0;
  setTimeout(()=>{if(st){s1.classList.add("hidden");s2.classList.remove("hidden");}else{s2.classList.add("hidden");s1.classList.remove("hidden");}st=!st;sw.style.opacity=1;},700);
 },4000);
}

/* ---------------- WHATSAPP BUBBLE ---------------- */
setTimeout(()=>{const b=document.querySelector(".whatsapp-bubble");if(b)b.style.display="none";},5000);

/* ---------------- PARALLAX (debounced) ---------------- */
let pto;
window.addEventListener("scroll",()=>{clearTimeout(pto);pto=setTimeout(()=>{
 const y=window.pageYOffset;
 document.querySelectorAll(".parallax").forEach((el,i)=>{el.style.transform=`translateY(${y*(0.15*(i+1))}px)`});
},10);});

/* ---------------- CARD SCROLL ANIMATIONS ---------------- */
const cards=document.querySelectorAll("[data-animate]");
if(cards.length){
 const io=new IntersectionObserver((e)=>{
  e.forEach(x=>{
   if(x.isIntersecting){
    let d=x.target.dataset.delay||0;
    x.target.style.transitionDelay=d+"ms";
    x.target.classList.add("animate-in");
    io.unobserve(x.target);
   }
  })
 },{threshold:.25});
 cards.forEach(c=>io.observe(c));
}

});
